//! Typed `cmux.wire/1` client types for the cmux Cloud ops.
//!
//! Every op of `backend/catalog/cloud-operations.json` (the ops the
//! TypeScript client in `clients/ts/cloud` exposes; internal ops are not in
//! the catalog) has a marker type that implements [`Op`]: its name, class,
//! idempotency rule, params struct, result type and an error enum of the
//! codes its catalog row declares. The types are generated by
//! `backend/packages/protocol/scripts/export-rust-client.ts` into
//! `src/generated/`; `bun run catalog:check` fails when the catalog changes
//! without a regeneration, and `tests/cloud_vectors.rs` round-trips every
//! case of `backend/catalog/cloud-vectors.json` through them
//! (plans/cmux-next/mobile-rust-core.md, MOBILE-RUST-3).
//!
//! The crate is sans-I/O: no transport, no HTTP, no runtime. The envelope
//! ([`OpRequest`], [`ReadResponse`], [`OpResponse`], [`HttpError`]) mirrors
//! `backend/packages/protocol/src/api.ts`.
//!
//! Field names are the catalog's. An optional field is `Option<T>` and is
//! left out when `None`; an optional field that may also be `null` is
//! `Option<Option<T>>`. Forward compatibility: a newer backend must not break
//! an older client, so a string enum with more than one value, an op's error
//! enum and a union each keep what this build does not know in an `Unknown`
//! variant (the value verbatim). A single-value enum is a strict literal, so
//! union members stay distinct.

#![forbid(unsafe_code)]

#[macro_use]
mod macros;
mod envelope;
mod op;
mod value;

#[rustfmt::skip]
#[allow(
    clippy::large_enum_variant,
    clippy::upper_case_acronyms,
    clippy::enum_variant_names,
    unused_qualifications
)]
mod generated;

pub use envelope::{HttpError, OpError, OpRequest, OpResponse, Origin, ReadResponse};
pub use generated::*;
pub use op::{Op, OpVisitor, WireClass, WireError, WireIdempotency, WirePrincipal};
pub use value::{BoolLit, WireNumber};
